window.NEON_UPLOADED_MAASER10_ZERO_LESSON1_20260828 = [{"id":"qdq-maaser10-zero1-001","q":"أوجد ناتج المقدار: ٥ + ٧(١١ - ٨)² + ٦ ÷ ٣ - ٤","options":["٣٥","٤٢","٦٦","٧٥"],"answer":2,"explain":"نحسب داخل القوس والأس أولًا: (١١-٨)²=٩، ثم ٧×٩=٦٣، و٦÷٣=٢، فيكون الناتج ٥+٦٣+٢-٤=٦٦.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"arithmetic","level":"foundation","source":"تفريغ تعليمي من الفيديو المرفوع: شرح كتاب المعاصر 10 - الباب زيرو (الدرس 1) - مستر خيري"},{"id":"qdq-maaser10-zero1-002","q":"أوجد قيمة المقدار: ٨² - ١٦ ÷ (٢ × ٤)","options":["٨","٣٢","٦٢","٩٦"],"answer":2,"explain":"٨²=٦٤، و(٢×٤)=٨، ثم ١٦÷٨=٢، إذن ٦٤-٢=٦٢.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"arithmetic","level":"foundation","source":"تفريغ تعليمي من الفيديو المرفوع: شرح كتاب المعاصر 10 - الباب زيرو (الدرس 1) - مستر خيري"},{"id":"qdq-maaser10-zero1-003","q":"أي الآتي يساوي ١١؟","options":["١٠ + ٦ ÷ ٢ + ٣","(٣ × ٢) + ٤ + (٥ ÷ ٥)","٨ + ٢ ÷ ٢ + ٦","(٥ × ٣) - (٤ ÷ ٢)"],"answer":1,"explain":"(٣×٢)+٤+(٥÷٥)=٦+٤+١=١١.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"arithmetic","level":"foundation","source":"تفريغ تعليمي من الفيديو المرفوع: شرح كتاب المعاصر 10 - الباب زيرو (الدرس 1) - مستر خيري"},{"id":"qdq-maaser10-zero1-004","q":"أي العبارات الآتية صحيحة؟","options":["١ + ٢ × ٢ = ٦","٢ × ١ + ٢ = ٦","٢ + ١ × ٢ = ٤","٢ × ١ ÷ ٢ = ٤"],"answer":2,"explain":"بحسب ترتيب العمليات: ١×٢=٢ ثم ٢+٢=٤، لذا العبارة الثالثة صحيحة.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"arithmetic","level":"foundation","source":"تفريغ تعليمي من الفيديو المرفوع: شرح كتاب المعاصر 10 - الباب زيرو (الدرس 1) - مستر خيري"},{"id":"qdq-maaser10-zero1-005","q":"قارن بين القيمة الأولى: ١٦ ÷ ٨ × ٤، والقيمة الثانية: ٨ × ٤ ÷ ١٦.","options":["القيمة الأولى أكبر","القيمة الثانية أكبر","القيمتان متساويتان","المعلومات غير كافية"],"answer":0,"explain":"القيمة الأولى = ٨، والقيمة الثانية = ٢، لذلك القيمة الأولى أكبر.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"arithmetic","level":"foundation","source":"تفريغ تعليمي من الفيديو المرفوع: شرح كتاب المعاصر 10 - الباب زيرو (الدرس 1) - مستر خيري"},{"id":"qdq-maaser10-zero1-006","q":"ما قيمة (٢³ + ٥) × ٧ - ٤؟","options":["٨٧","٨١","٩١","٩٥"],"answer":0,"explain":"٢³=٨، ثم (٨+٥)×٧-٤=١٣×٧-٤=٨٧.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"arithmetic","level":"foundation","source":"تفريغ تعليمي من الفيديو المرفوع: شرح كتاب المعاصر 10 - الباب زيرو (الدرس 1) - مستر خيري"},{"id":"qdq-maaser10-zero1-007","q":"ما ناتج المقدار: ١٠ - ٦ ÷ ٣ × ٢؟","options":["٤","٥","٦","٣"],"answer":2,"explain":"القسمة والضرب أولًا من اليسار: ٦÷٣×٢=٤، ثم ١٠-٤=٦.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"arithmetic","level":"foundation","source":"تفريغ تعليمي من الفيديو المرفوع: شرح كتاب المعاصر 10 - الباب زيرو (الدرس 1) - مستر خيري"},{"id":"qdq-maaser10-zero1-008","q":"إذا كان ٤ .... ٣ .... ٣ = ١٥، فما العمليتان الصحيحتان على الترتيب؟","options":["× ثم +","+ ثم ×","× ثم ×","+ ثم +"],"answer":0,"explain":"٤×٣+٣=١٢+٣=١٥.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"arithmetic","level":"foundation","source":"تفريغ تعليمي من الفيديو المرفوع: شرح كتاب المعاصر 10 - الباب زيرو (الدرس 1) - مستر خيري"},{"id":"qdq-maaser10-zero1-009","q":"أوجد قيمة المقدار: ٧٧ - ٧ × ٧٧ × (١١ ÷ ٧٧).","options":["صفر","٧٧","٧","٧٧٠"],"answer":0,"explain":"٧٧×(١١÷٧٧)=١١، ثم ٧×١١=٧٧، وبالتالي ٧٧-٧٧=صفر.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"arithmetic","level":"foundation","source":"تفريغ تعليمي من الفيديو المرفوع: شرح كتاب المعاصر 10 - الباب زيرو (الدرس 1) - مستر خيري"},{"id":"qdq-maaser10-zero1-010","q":"ما ناتج جمع أول ٥٠ حدًا من المتتابعة: ٣، ٣، ٣، ٣، ...؟","options":["٥٠","٣٠","١٥٠","١٥٠٠"],"answer":2,"explain":"كل حد يساوي ٣، وعدد الحدود ٥٠، إذن المجموع ٥٠×٣=١٥٠.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"arithmetic","level":"foundation","source":"تفريغ تعليمي من الفيديو المرفوع: شرح كتاب المعاصر 10 - الباب زيرو (الدرس 1) - مستر خيري"},{"id":"qdq-maaser10-zero1-011","q":"ما ناتج جمع ٣/٤٠ مع نفسها ٢٠ مرة؟","options":["٣","٢٠","٣/٢٠","٣/٢"],"answer":3,"explain":"٢٠×(٣/٤٠)=٦٠/٤٠=٣/٢.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"arithmetic","level":"foundation","source":"تفريغ تعليمي من الفيديو المرفوع: شرح كتاب المعاصر 10 - الباب زيرو (الدرس 1) - مستر خيري"},{"id":"qdq-maaser10-zero1-012","q":"ما قيمة √(٦٤ + ٦٤ + ٦٤ + ٦٤)؟","options":["٨","١٦","٣٢","٦٤"],"answer":1,"explain":"المجموع داخل الجذر ٢٥٦، وجذر ٢٥٦ يساوي ١٦.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"arithmetic","level":"foundation","source":"تفريغ تعليمي من الفيديو المرفوع: شرح كتاب المعاصر 10 - الباب زيرو (الدرس 1) - مستر خيري"},{"id":"qdq-maaser10-zero1-013","q":"بسّط المقدار: ٥¹⁸ + ٥¹⁸ + ٥¹⁸ + ٥¹⁸ + ٥¹⁸.","options":["٢٥¹⁸","٥¹⁹","٢٥¹⁹","٥¹⁸"],"answer":1,"explain":"لدينا خمسة حدود متساوية: ٥×٥¹⁸=٥¹⁹.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"arithmetic","level":"foundation","source":"تفريغ تعليمي من الفيديو المرفوع: شرح كتاب المعاصر 10 - الباب زيرو (الدرس 1) - مستر خيري"},{"id":"qdq-maaser10-zero1-014","q":"قارن بين القيمة الأولى: (٧٧ + ٧٧ + ٧٧ + ٧٧) ÷ ٧، والقيمة الثانية: ٧٧.","options":["القيمة الأولى أكبر","القيمة الثانية أكبر","القيمتان متساويتان","المعلومات غير كافية"],"answer":1,"explain":"القيمة الأولى = ٣٠٨÷٧=٤٤، وهي أقل من ٧٧.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"arithmetic","level":"foundation","source":"تفريغ تعليمي من الفيديو المرفوع: شرح كتاب المعاصر 10 - الباب زيرو (الدرس 1) - مستر خيري"},{"id":"qdq-maaser10-zero1-015","q":"أوجد قيمة: ١¹ + ١² + ١³ + ... + ١¹⁴³³.","options":["١","١٤٣٣","١٤٣٣١","١١١٣٣"],"answer":1,"explain":"كل قوة للعدد ١ تساوي ١، وعدد الحدود ١٤٣٣، إذن المجموع ١٤٣٣.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"arithmetic","level":"foundation","source":"تفريغ تعليمي من الفيديو المرفوع: شرح كتاب المعاصر 10 - الباب زيرو (الدرس 1) - مستر خيري"},{"id":"qdq-maaser10-zero1-016","q":"أوجد قيمة: ٩٩٠ + ١٠ + ٦٥٠ + ٣٥٠ + ٧٠٠ + ٨٢٠ + ١٨٠ + ٣٠٠ + ٢٥٠ + ٧٥٠.","options":["٥٠٠٠","٥٥٠٠","٤٥٠٠","٦٠٠٠"],"answer":0,"explain":"نكوّن أزواجًا مجموع كل منها ١٠٠٠: ٩٩٠+١٠، ٦٥٠+٣٥٠، ٧٠٠+٣٠٠، ٨٢٠+١٨٠، ٧٥٠+٢٥٠؛ فيكون المجموع ٥٠٠٠.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"arithmetic","level":"foundation","source":"تفريغ تعليمي من الفيديو المرفوع: شرح كتاب المعاصر 10 - الباب زيرو (الدرس 1) - مستر خيري"},{"id":"qdq-maaser10-zero1-017","q":"ما قيمة: ٠٫١ + ٠٫٢ + ٠٫٣ + ٠٫٤ + ... + ٠٫٩؟","options":["٣٫٥","٤","٤٫٥","٥"],"answer":2,"explain":"المجموع = (١+٢+...+٩)÷١٠ = ٤٥÷١٠ = ٤٫٥.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"arithmetic","level":"foundation","source":"تفريغ تعليمي من الفيديو المرفوع: شرح كتاب المعاصر 10 - الباب زيرو (الدرس 1) - مستر خيري"},{"id":"qdq-maaser10-zero1-018","q":"أوجد ناتج: ١² + ٢² + ٣² + ... + ١٠².","options":["٣٨٠","٣٨٥","٣٩٠","٣٩٥"],"answer":1,"explain":"مجموع مربعات الأعداد من ١ إلى ١٠ يساوي ٣٨٥.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"arithmetic","level":"foundation","source":"تفريغ تعليمي من الفيديو المرفوع: شرح كتاب المعاصر 10 - الباب زيرو (الدرس 1) - مستر خيري"},{"id":"qdq-maaser10-zero1-019","q":"قارن بين القيمة الأولى: (٩٩ + ٧٧ + ٦٦ + ٥٥) ÷ (٥٥ + ٤٤)، والقيمة الثانية: ٣.","options":["القيمة الأولى أكبر","القيمة الثانية أكبر","القيمتان متساويتان","المعلومات غير كافية"],"answer":2,"explain":"البسط ٢٩٧ والمقام ٩٩، إذن القيمة الأولى =٣، فتتساوى القيمتان.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"arithmetic","level":"foundation","source":"تفريغ تعليمي من الفيديو المرفوع: شرح كتاب المعاصر 10 - الباب زيرو (الدرس 1) - مستر خيري"},{"id":"qdq-maaser10-zero1-020","q":"قارن بين القيمة الأولى: (٣٥ + ٢٨ + ٢١ + ١٤ + ٧) ÷ ٢١، والقيمة الثانية: ٧.","options":["القيمة الأولى أكبر","القيمة الثانية أكبر","القيمتان متساويتان","المعلومات غير كافية"],"answer":1,"explain":"مجموع البسط ١٠٥، وبالقسمة على ٢١ تكون القيمة الأولى ٥، وهي أقل من ٧.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"arithmetic","level":"foundation","source":"تفريغ تعليمي من الفيديو المرفوع: شرح كتاب المعاصر 10 - الباب زيرو (الدرس 1) - مستر خيري"},{"id":"qdq-maaser10-zero1-021","q":"أوجد مجموع أول ١٠٠ عدد طبيعي.","options":["٦٢٥","٣٣٢٥","٥٠٥٠","٦٧٥٠"],"answer":2,"explain":"١+٢+...+١٠٠ = ١٠٠×١٠١÷٢ = ٥٠٥٠.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"arithmetic","level":"foundation","source":"تفريغ تعليمي من الفيديو المرفوع: شرح كتاب المعاصر 10 - الباب زيرو (الدرس 1) - مستر خيري"},{"id":"qdq-maaser10-zero1-022","q":"ما مجموع الأعداد الصحيحة من ٠٫٥ إلى ٩٠٫٥؟","options":["٤٠٩٥","٩٠٠٠","٥٩٠٠","٦٢٢٥"],"answer":0,"explain":"الأعداد الصحيحة الواقعة بينهما هي ١ إلى ٩٠، ومجموعها ٩٠×٩١÷٢ = ٤٠٩٥.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"arithmetic","level":"foundation","source":"تفريغ تعليمي من الفيديو المرفوع: شرح كتاب المعاصر 10 - الباب زيرو (الدرس 1) - مستر خيري"},{"id":"qdq-maaser10-zero1-023","q":"أوجد ناتج: (١ + ٢ + ٣ + ... + ١٠)².","options":["١٢٢٥","٢٠٢٥","٣٠٢٥","٣٢٢٥"],"answer":2,"explain":"مجموع ١ إلى ١٠ يساوي ٥٥، و٥٥²=٣٠٢٥.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"arithmetic","level":"foundation","source":"تفريغ تعليمي من الفيديو المرفوع: شرح كتاب المعاصر 10 - الباب زيرو (الدرس 1) - مستر خيري"},{"id":"qdq-maaser10-zero1-024","q":"أوجد ناتج: ١٠ + ٢٠ + ٣٠ + ... + ٩٠.","options":["٢٢٥","٣٧٥","٤٢٥","٤٥٠"],"answer":3,"explain":"١٠(١+٢+...+٩)=١٠×٤٥=٤٥٠.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"arithmetic","level":"foundation","source":"تفريغ تعليمي من الفيديو المرفوع: شرح كتاب المعاصر 10 - الباب زيرو (الدرس 1) - مستر خيري"},{"id":"qdq-maaser10-zero1-025","q":"أوجد ناتج: ١ + ٢ + ٣ + ٤ + ٥ + ... + ٤٠.","options":["٤١٠","٨٢٠","٩٢٠","١٦٤١"],"answer":1,"explain":"مجموع أول ٤٠ عددًا طبيعيًا = ٤٠×٤١÷٢ = ٨٢٠.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"arithmetic","level":"foundation","source":"تفريغ تعليمي من الفيديو المرفوع: شرح كتاب المعاصر 10 - الباب زيرو (الدرس 1) - مستر خيري"},{"id":"qdq-maaser10-zero1-026","q":"قطار سعته ٩١ راكبًا. في المحطة الأولى يدخل راكب واحد، وفي الثانية راكبان، وفي الثالثة ٣ ركاب، وهكذا؛ في كل محطة يدخل عدد من الركاب يساوي رقم المحطة. في أي محطة يمتلئ القطار؟","options":["١١","١٣","١٥","١٧"],"answer":1,"explain":"نحتاج n(n+1)/2=٩١. عند n=١٣ نحصل على ١٣×١٤÷٢=٩١.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"arithmetic","level":"foundation","source":"تفريغ تعليمي من الفيديو المرفوع: شرح كتاب المعاصر 10 - الباب زيرو (الدرس 1) - مستر خيري"},{"id":"qdq-maaser10-zero1-027","q":"أوجد ناتج: (٢ + ٤ + ٦ + ... + ٣٢) - (١ + ٣ + ٥ + ... + ٣٣).","options":["٣٣","-٣٣","١٧","-١٧"],"answer":3,"explain":"مجموع الأزواج ٢ إلى ٣٢ =٢٧٢، ومجموع الأعداد الفردية ١ إلى ٣٣ =٢٨٩، فالفرق = -١٧.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"arithmetic","level":"foundation","source":"تفريغ تعليمي من الفيديو المرفوع: شرح كتاب المعاصر 10 - الباب زيرو (الدرس 1) - مستر خيري"},{"id":"qdq-maaser10-zero1-028","q":"أوجد ناتج: ١٠٠ - ٩٩ + ٩٨ - ٩٧ + ... + ٤ - ٣ + ٢ - ١.","options":["٥٠","١٠٠","٥٠٠","١٠٠٠"],"answer":0,"explain":"نجمع كل زوج: (١٠٠-٩٩)+(٩٨-٩٧)+...+(٢-١)، وعدد الأزواج ٥٠، فالناتج ٥٠.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"arithmetic","level":"foundation","source":"تفريغ تعليمي من الفيديو المرفوع: شرح كتاب المعاصر 10 - الباب زيرو (الدرس 1) - مستر خيري"},{"id":"qdq-maaser10-zero1-029","q":"ما الفرق بين أكبر عدد زوجي مكوّن من ٤ أرقام وأصغر عدد فردي مكوّن من ٤ أرقام؟","options":["٧٨٩٧","٨٩٩٨","٨٩٩٧","٧٧٨٨"],"answer":2,"explain":"أكبر عدد زوجي من ٤ أرقام هو ٩٩٩٨، وأصغر عدد فردي من ٤ أرقام هو ١٠٠١؛ الفرق ٨٩٩٧.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"arithmetic","level":"foundation","source":"تفريغ تعليمي من الفيديو المرفوع: شرح كتاب المعاصر 10 - الباب زيرو (الدرس 1) - مستر خيري"},{"id":"qdq-maaser10-zero1-030","q":"في الأعداد ١، ٢، ٣، ٤، ...، ١٩ قارن بين القيمة الأولى: مجموع الأعداد الفردية، والقيمة الثانية: مجموع الأعداد الزوجية.","options":["القيمة الأولى أكبر","القيمة الثانية أكبر","القيمتان متساويتان","المعلومات غير كافية"],"answer":0,"explain":"الأعداد الفردية من ١ إلى ١٩ مجموعها ١٠٠، والزوجية من ٢ إلى ١٨ مجموعها ٩٠، لذا القيمة الأولى أكبر.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"arithmetic","level":"foundation","source":"تفريغ تعليمي من الفيديو المرفوع: شرح كتاب المعاصر 10 - الباب زيرو (الدرس 1) - مستر خيري"},{"id":"qdq-maaser10-zero1-031","q":"في الأعداد ٥، ٦، ٧، ٨، ...، ٢٥ قارن بين القيمة الأولى: مجموع الأعداد الفردية، والقيمة الثانية: مجموع الأعداد الزوجية.","options":["القيمة الأولى أكبر","القيمة الثانية أكبر","القيمتان متساويتان","المعلومات غير كافية"],"answer":0,"explain":"مجموع الفردية من ٥ إلى ٢٥ =١٦٥، ومجموع الزوجية من ٦ إلى ٢٤ =١٥٠، لذا القيمة الأولى أكبر.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"arithmetic","level":"foundation","source":"تفريغ تعليمي من الفيديو المرفوع: شرح كتاب المعاصر 10 - الباب زيرو (الدرس 1) - مستر خيري"},{"id":"qdq-maaser10-zero1-032","q":"ما الرقم في خانة الآحاد للعدد: ٤٥٣٢ × ٣٧٥٧٦٥ × ٥٩٩٨٧٨؟","options":["صفر","١","٢","٣"],"answer":0,"explain":"يكفي ضرب الآحاد: ٢×٥×٨=٨٠، إذن رقم الآحاد صفر.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"arithmetic","level":"foundation","source":"تفريغ تعليمي من الفيديو المرفوع: شرح كتاب المعاصر 10 - الباب زيرو (الدرس 1) - مستر خيري"},{"id":"qdq-maaser10-zero1-033","q":"أوجد حاصل ضرب جميع الأعداد الكلية.","options":["صفر","١٠٠٠٠٠","١٠٠٠٠٠٠","٩٩٩٩٩٩"],"answer":0,"explain":"الأعداد الكلية تتضمن الصفر، وأي حاصل ضرب يتضمن الصفر يساوي صفرًا.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"arithmetic","level":"foundation","source":"تفريغ تعليمي من الفيديو المرفوع: شرح كتاب المعاصر 10 - الباب زيرو (الدرس 1) - مستر خيري"},{"id":"qdq-maaser10-zero1-034","q":"أوجد رقم الآحاد للناتج: (١ + ٢ + ٣ + ... + ١٠)².","options":["صفر","١","٣","٥"],"answer":3,"explain":"المجموع ٥٥، و٥٥²=٣٠٢٥، إذن رقم الآحاد ٥.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"arithmetic","level":"foundation","source":"تفريغ تعليمي من الفيديو المرفوع: شرح كتاب المعاصر 10 - الباب زيرو (الدرس 1) - مستر خيري"},{"id":"qdq-maaser10-zero1-035","q":"ما ناتج: ٨٧٩٥٦٢٢٠ ÷ ٢٨٤؟","options":["٣٠٩٧٠٥","٣٠٩٧٠٤","٣٠٩٧٠٣","٣٠٩٧٠٦"],"answer":0,"explain":"٨٧٩٥٦٢٢٠ ÷ ٢٨٤ = ٣٠٩٧٠٥.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"arithmetic","level":"foundation","source":"تفريغ تعليمي من الفيديو المرفوع: شرح كتاب المعاصر 10 - الباب زيرو (الدرس 1) - مستر خيري"},{"id":"qdq-maaser10-zero1-036","q":"أوجد رقم خانة العشرات في العدد: ٣٤٧٥ × ٦١٣٢.","options":["٣","٧","٩","صفر"],"answer":3,"explain":"لتحديد آخر رقمين يكفي ٧٥×٣٢=٢٤٠٠، إذن رقم العشرات صفر.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"arithmetic","level":"foundation","source":"تفريغ تعليمي من الفيديو المرفوع: شرح كتاب المعاصر 10 - الباب زيرو (الدرس 1) - مستر خيري"},{"id":"qdq-maaser10-zero1-037","q":"ما رقم خانة العشرات في العدد: (١ × ٢ × ٣ × ٤ × ٥) × (٥ × ٤ × ٣ × ٢ × ١)؟","options":["٢","٥","٤","صفر"],"answer":3,"explain":"كل قوس يساوي ١٢٠، وحاصل الضرب ١٤٤٠٠، لذا رقم العشرات صفر.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"arithmetic","level":"foundation","source":"تفريغ تعليمي من الفيديو المرفوع: شرح كتاب المعاصر 10 - الباب زيرو (الدرس 1) - مستر خيري"},{"id":"qdq-maaser10-zero1-038","q":"قارن بين القيمة الأولى: ١١٢ × ٩٧، والقيمة الثانية: ١١١ × ٩٨.","options":["القيمة الأولى أكبر","القيمة الثانية أكبر","القيمتان متساويتان","المعلومات غير كافية"],"answer":1,"explain":"القيمة الأولى ١٠٨٦٤، والثانية ١٠٨٧٨، لذا القيمة الثانية أكبر.","area":"exams","family":"qudurat","subject":"qudurat-quant","category":"arithmetic","level":"foundation","source":"تفريغ تعليمي من الفيديو المرفوع: شرح كتاب المعاصر 10 - الباب زيرو (الدرس 1) - مستر خيري"}];
